export const articles:Article[]=[
{slug:"vinfast-vf3-best-selling-bev-philippines-2026",category:"VINFAST NEWS",title:"VinFast VF 3 leads battery EV sales among CAMPI-TMA reported brands in the Philippines",dek:"With 2,906 units sold from January to August 2026, the VinFast VF 3 ranked as the top-selling battery electric vehicle among CAMPI-TMA reported brands.",date:"27 October 2026",hero:vf3BestSellerHero,images:[],facts:["2,906 units sold","January–August 2026","Top-selling BEV among CAMPI-TMA reported brands"],sections:[{heading:"A small EV reaches a major milestone",paragraphs:["The VinFast VF 3 recorded 2,906 units sold from January to August 2026, making it the top-selling battery electric vehicle among brands reported by CAMPI-TMA for the period.","Compact, affordable and well suited to city driving, the VF 3 has quickly become one of the most visible electric vehicles in the Philippine market."]},{heading:"A proud milestone for a Vietnamese brand",paragraphs:["For DT Car Philippines, the result carries special meaning. Seeing a Vietnamese automotive brand gain recognition in the Philippine market reflects the growing acceptance of practical electric mobility.","As Lisa Dong of DT Car Philippines put it: small car, big achievement — a milestone connecting Vietnam and the Philippines through a growing EV market."]},{heading:"What comes next",paragraphs:["DT Car is looking ahead to the next chapter of the VF 3 story, including the upcoming VF 3 Eco and Plus variants.","Source: CAMPI-TMA. The ranking above refers to CAMPI-TMA reported brands and excludes non-member brands."]}]},
{slug:"vinfast-authorized-workshop-network",category:"WORKSHOP",title:"Building dependable after-sales support through 12 service workshops",dek:"DT Car's workshop network brings technical coordination, vehicle inspection, maintenance and after-sales support closer to customers across the Philippines.",date:"13 August 2026",hero:I("235993FA-122C-4900-BD39-EAC455381A5A.jpeg"),images:[I("story-engineering.jpeg"),I("ECE516B8-B6C5-4569-8367-E65DFE59ECB0.jpeg"),I("235993FA-122C-4900-BD39-EAC455381A5A.jpeg")],facts:["12 service workshops","Authorized VinFast service partner","Inspection, maintenance and technical support"],sections:[{heading:"A service network built around ownership",paragraphs:["Buying a vehicle is only the beginning. DT Car has developed a network of 12 service workshops so customers can reach technical and after-sales support with greater consistency.","Workshop teams support vehicle inspection, maintenance, repair coordination and practical customer care through clear intake, technical review and accountable delivery."]},{heading:"Local execution, shared standards",paragraphs:["DT Car combines local operating knowledge with partner requirements. The model is designed for Philippine conditions while maintaining the standards expected of an authorized VinFast service partner.","As electric mobility develops, reliable service capacity remains central to confidence. DT Car continues to strengthen workshop readiness, technician coordination and customer communication."]}]},
{slug:"pre-owned-cars-professional-inspection",category:"PRE-OWNED VEHICLES",title:"A more professional way to buy and sell pre-owned vehicles",dek:"From family cars to premium models, DT Car brings sourcing, inspection and transparent coordination into one customer journey.",date:"13 August 2026",hero:used[0],images:used.slice(1),facts:["Multi-brand sourcing","Vehicle condition review","Clear transaction support"],sections:[{heading:"Not a classified listing — a guided transaction",paragraphs:["DT Car's pre-owned vehicle business is a showroom and advisory service, not simply a page of listings. The team helps buyers define their needs and sellers present vehicles with the information required for a serious transaction.","Brand, model, usage, visible condition, documents and budget are reviewed before the process moves forward."]},{heading:"Inspection before confidence",paragraphs:["A pre-owned vehicle deserves more than attractive photography. DT Car coordinates physical checks and condition review so customers can understand what they are considering.","The gallery reflects the range handled by the team—from Toyota, Ford, Suzuki and Honda to Lexus, BMW, Audi, Mercedes-Benz, Volvo, Nissan and other brands."]},{heading:"Human support through handover",paragraphs:["The team remains involved through viewing, negotiation, document coordination and handover, reducing avoidable uncertainty for both parties.","Current inventory is shared through DT Car's official language-specific Facebook pages. This website introduces the service and connects visitors to the right team; it is not an online car marketplace."]}]},
{slug:"vinfast-sales-and-customer-handover",category:"VINFAST SALES",title:"From showroom consultation to a carefully prepared VinFast handover",dek:"As an official VinFast sales representative, DT Car supports customers with product consultation, coordination and delivery.",date:"13 August 2026",hero:I("story-showroom.jpeg"),images:[I("story-vinfast-lifestyle.jpeg"),I("story-handover.jpeg"),I("story-customer.jpeg"),I("story-event.jpeg"),I("vinfast-award.jpeg"),I("story-partner.jpeg"),I("741775D9-9727-44C4-B127-D519A5369B65.jpeg"),I("D172B719-E9D5-4552-A124-F5E5D0E5BD54.jpeg"),I("3F8E4FC3-5634-48A1-82FB-CD13C8C3F1F9.jpeg"),I("05CFF962-4587-4C8E-8780-9465445281AE.jpeg"),I("7F0F8F04-59C3-45DC-AA31-FBC480DA9061.jpeg")],sections:[{heading:"An official sales relationship",paragraphs:["DT Car serves as an official VinFast vehicle sales representative in the Philippines, bringing together consultation, product introduction, appointment coordination and handover support.","The team helps customers understand the vehicle and routes after-sales needs into the wider DT Car service network."]},{heading:"The handover is part of the experience",paragraphs:["A vehicle delivery is a meaningful milestone. DT Car prepares each handover so the customer can review the vehicle, receive practical orientation and leave with a clear point of contact.","Official events and partner activities also build a connected ownership community around the growing VinFast brand."]}]},
{slug:"vinfast-delivery-emmanuelle-tiglao",category:"SPECIAL DELIVERY",title:"DT Car joins the VinFast handover for Miss Universe Philippines 2025 Emmanuelle Tiglao",dek:"A dedicated story from a memorable delivery—bringing together VinFast, DT Car and one of the Philippines' most recognized public figures.",date:"13 August 2026",hero:I("0437D0EE-D496-4E39-AE62-FBBED4F4CC96.jpeg"),images:[I("A8AC75D5-800C-4D4B-883F-D0C34022B547.jpeg")],sections:[{heading:"A handover worthy of its own story",paragraphs:["This was not a generic customer image. It marked the presentation of a VinFast vehicle to Miss Universe Philippines 2025 Emmanuelle ‘Emman’ Tiglao, with DT Car represented as part of the customer and partner experience.","The occasion reflects the visibility of electric mobility in the Philippines and the importance of presenting every delivery with care and professionalism."]},{heading:"More than a photo opportunity",paragraphs:["Behind the ceremonial key are the same fundamentals applied to every DT Car handover: coordination, vehicle readiness, product orientation and an accessible after-sales connection.","DT Car is proud to support moments that introduce VinFast vehicles to new audiences while keeping the focus on dependable service after the event."]}]},
{slug:"gsm-10000-vehicle-technology-rollout",category:"GSM PROJECT",title:"Inside a 10,000+ vehicle rollout: stickers, SIM dash cams, taxi meters and software",dek:"DT Car supports both Green and premium LimoGreen fleets through coordinated, repeatable installation and operational work.",date:"13 August 2026",hero:I("3C6CC438-ADE7-4E76-B073-117DB97C78A0.jpeg"),images:[I("gsm-fleet.jpeg"),I("story-gsm-overview.jpeg"),I("story-limogreen.jpeg"),I("EE46C4E6-9F78-416E-B585-9AAE2DA7B274.jpeg"),I("6F53F67D-A5E1-4A3F-861A-B98108F6A9FB.jpeg"),I("4889B5B5-7640-48DA-A760-9E271B2470D0.jpeg")],facts:["10,000+ vehicles across all scopes","Green and premium LimoGreen","Installation and operational support"],sections:[{heading:"Scale depends on repeatable execution",paragraphs:["DT Car has supported more than 10,000 GSM vehicles across all project scopes: visual identity stickers, SIM-enabled dash cameras, taxi meters, software setup and other preparation required before operation.","Teams, equipment, quality checks and reporting are coordinated so each vehicle moves through the required stages with traceability."]},{heading:"One program, two service segments",paragraphs:["The scope includes both the familiar green fleet and premium LimoGreen vehicles. While the customer experience differs, installation quality and operational readiness remain non-negotiable.","DT Car also supports vehicle supply, rental, repair and maintenance, reducing fragmentation across the fleet lifecycle."]}]},
{slug:"vinfast-car-owners-event",category:"VINFAST OWNERS EVENT",title:"Building connection beyond the showroom: a dedicated event for VinFast car owners",dek:"DT Car supported a community gathering created for VinFast owners—bringing customers, product teams and partners together around a shared ownership experience.",date:"13 August 2026",hero:I("ADA2D56D-6A8A-41EE-AEE3-B741805613BB.jpeg"),images:[I("0985D8FD-9730-4E2C-82C5-65C1DA395913.jpeg"),I("7DA3424E-7D5C-49E0-9091-5B4C7D29144B.jpeg"),I("EFFB33F7-8AD7-4BC1-8B90-4A6A9BA94381.jpeg")],facts:["VinFast owner community","Customer engagement","Event coordination"],sections:[{heading:"An event centered on owners",paragraphs:["The group photograph with the VinFast banner records a dedicated car-owner event, not a driver-recruitment activity. DT Car helped create an environment where owners could meet, exchange experiences and connect directly with people supporting the brand.","The program extended the relationship beyond the point of sale and gave customers a visible community around their vehicles."]},{heading:"Ownership continues after handover",paragraphs:["Strong automotive brands are built through consistent experiences after delivery. Events such as this create opportunities for product conversation, practical feedback and a closer link to sales and after-sales teams.","For DT Car, event support is part of a broader commitment to customer care: consultation, handover, workshop access and ongoing community engagement should feel connected rather than separate."]},{heading:"Local execution for a growing brand",paragraphs:["DT Car combines venue and participant coordination with on-the-ground knowledge of the Philippine market. Every detail—from the vehicle line-up to owner communication and documentation—contributes to a professional brand experience.","The event reflects a simple principle behind DT Car's work: Drive Trust by staying present throughout the ownership journey."]}]},
{slug:"xentro-mall-fleet-installation",category:"XENTRO MALL",title:"DT Car completes integrated vehicle installation work for Xentro Mall",dek:"Sticker application, SIM dash cams and taxi meters are coordinated as one field program for consistent delivery.",date:"13 August 2026",hero:I("story-xentro.jpeg"),images:[I("story-xentro-team.jpeg"),I("546FA152-5BFB-43BA-B9C2-947DD848CB6F.jpeg")],sections:[{heading:"A dedicated implementation scope",paragraphs:["The Xentro Mall program is a distinct client engagement. DT Car's role includes vehicle stickers, SIM-enabled dash camera installation and taxi-meter work.","Each element has its own requirements, but delivery is managed as one workflow to reduce disruption and keep responsibility clear."]},{heading:"Field coordination makes the difference",paragraphs:["Successful rollout depends on scheduling, material readiness, installation sequence and final checking. DT Car brings these pieces together and bridges partner requirements with work on the ground."]}]},
{slug:"green-gsm-driver-recruitment",category:"DRIVER RECRUITMENT",title:"Recruiting the people behind the wheel for Green GSM",dek:"Vehicle readiness is only one part of mobility operations. DT Car also supports the driver recruitment program required to put fleets into service.",date:"13 August 2026",hero:I("4889B5B5-7640-48DA-A760-9E271B2470D0.jpeg"),images:[I("4889B5B5-7640-48DA-A760-9E271B2470D0.jpeg"),I("3C6CC438-ADE7-4E76-B073-117DB97C78A0.jpeg"),I("gsm-fleet.jpeg")],sections:[{heading:"People complete the operating system",paragraphs:["A fleet cannot create value while parked. Alongside vehicle preparation and technical rollout, DT Car supports GSM's driver recruitment project in the Philippines.","The work calls for local outreach, applicant coordination and clear communication. Driving-school and vehicle-registration services are not part of DT Car's current offering."]},{heading:"Connecting local talent with green mobility",paragraphs:["Driver recruitment links investment in electric vehicles with local employment. DT Car's local network helps the project reach prospective drivers and supports the flow needed to move candidates forward."]}]},
{slug:"vgreen-charging-network-philippines",category:"V-GREEN",title:"From more than 100 potential sites to four completed charging stations",dek:"DT Car supports V-Green with local site sourcing and construction coordination for a practical charging network.",date:"13 August 2026",hero:I("story-vgreen-site.jpeg"),images:[I("story-charger-build.jpeg"),I("story-charger-install.jpeg"),I("story-vgreen-team.jpeg"),I("story-vgreen-build-2.jpeg"),I("4D0D3D93-5BB1-4847-963C-C1E5300FB97E.jpeg"),I("51AF0593-C189-4BA6-9A6D-864EDC7616EE.jpeg"),I("55B14A7D-9C8B-4D2C-9CF9-1CFF3FE45383.jpeg"),I("75EB4193-CC00-4946-B2EF-CA859803D149.jpeg"),I("021961DF-05D9-4AFA-A1E0-612A71422F27.jpeg"),I("E9A44F15-106A-45EB-A5DE-9AC2CF4A45AF.jpeg"),I("A671233E-EC90-455F-A998-4EB560D67DF3.jpeg"),I("9A6002CC-9CDB-4741-B017-CA9B50E8FEE4.jpeg"),I("4B1C23FF-5A57-4B6A-98FF-C31C297C6E1C.jpeg"),I("FC3F4D40-F623-4924-AC58-94A241258638.jpeg"),I("D414F436-6B2D-4AC6-B9DD-E9981D856691.jpeg"),I("06128471-F493-4A48-9145-F1629E7FE6FF.jpeg")],facts:["100+ sites sourced","4 stations completed","Rephil, SB Oil and FERC Cebu opportunities"],sections:[{heading:"Finding viable ground",paragraphs:["Charging infrastructure begins long before equipment arrives. DT Car has sourced and evaluated more than 100 potential sites, including opportunities linked to Rephil, SB Oil and FERC Cebu.","Local site work brings access, commercial and technical considerations together, turning a location into a viable candidate."]},{heading:"Construction under real conditions",paragraphs:["Four charging stations have been completed. The imagery shows delivery, lifting, positioning, civil works, electrical preparation, safety control and final site organization.","DT Car continues to identify locations and build local execution capacity so charging can expand alongside vehicle adoption."]}]},
{slug:"meals-of-hope-community-program",category:"COMMUNITY",title:"Meals of Hope: DT Car joins the Philippine Army in community service",dek:"A DT Car charity activity, not a commercial project—bringing volunteers and service members together to support local communities.",date:"13 August 2026",hero:I("story-charity-team.jpeg"),images:[I("story-charity-group.jpeg"),I("story-community-drive.jpeg"),I("4A6EB230-AA4A-4E09-BD7F-1642C3B62615.jpeg"),I("9ADE0806-5C05-4EF1-B248-05A820732249.jpeg"),I("C9CE2C4F-FE6B-43C5-BFFA-8195FFC6F706.jpeg")],sections:[{heading:"Service beyond business",paragraphs:["The photographs with Philippine Army personnel document a DT Car charity activity. They are part of the company's community story, not a commercial or government contract.","Through Meals of Hope, volunteers joined local service members to prepare and distribute practical support."]},{heading:"Growing with the communities around us",paragraphs:["DT Car believes local partnership also means local responsibility. Community work allows the company and its people to contribute time, organization and resources beyond day-to-day business."]}]},
{slug:"dt-tour-philippines-curated-journeys",category:"DT TOUR",title:"DT Tour: Philippines journeys designed around people, not rigid packages",dek:"Private transport, local support and flexible itineraries connect beaches, heritage towns, forests, hot springs and islands.",date:"13 August 2026",hero:travel[5],images:travel.filter((_,i)=>i!==5),facts:["Private itineraries","Local coordination","Nature, heritage and island experiences"],sections:[{heading:"The Philippines, paced for the traveler",paragraphs:["DT Tour develops flexible journeys for individuals, couples, families and groups. The team combines local knowledge, private transport and practical coordination around the experience the traveler wants.","The portfolio ranges from yacht journeys and water sports to heritage architecture, forest pools, waterfalls, mountain weather and coastal sunsets."]},{heading:"Nature, history and the water",paragraphs:["A single itinerary can move from the preserved architecture of Las Casas to clear forest water, from a sunset viewpoint to a day at sea. Each location has a different rhythm.","Transport and local assistance are part of the travel experience, not an afterthought. The goal is a journey that feels supported without losing spontaneity."]},{heading:"A page dedicated to travel",paragraphs:["DT Tour has its own official Facebook page for current programs, route ideas and direct enquiries. Travel imagery and stories are kept separate from vehicle delivery, infrastructure and fleet projects throughout this website."]}]}
];
